{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Repirinast, a structurally related chromone/carboxylic acid, showed very low systemic availability after oral dosing with plasma concentrations below the limit of quantification, supporting F < 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Cromolyn, a chromone dicarboxylate with two ionized carboxylic acids, has oral bioavailability of less than 1% in humans, directly supporting low F for the similarly dianionic, highly polar query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Pefloxacin, a quinolone with one carboxylate and a basic piperazine, is nearly 100% orally bioavailable, but this high-F evidence transfers poorly because the query lacks a basic amine and contains two carboxylic acids.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural analogues with chromone/carboxylate motifs (repirinast, cromolyn) show very low oral systemic availability (<1% to below LOQ), consistent with the query's two ionized carboxylic acids, very low logD, and high TPSA. High-F quinolone evidence is poorly transferable because those molecules contain a basic amine and only one carboxylate. Therefore predict low.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data exist for the exact query molecule.",
    "No evidence addresses possible active transport that could overcome the unfavorable permeability.",
    "High-similarity analogues are limited; the closest direct low-F analogues have Morgan similarity below 0.32.",
    "High-F quinolone evidence is not transferable due to major differences in ionization and basic center content."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

